trial.program_source:
def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                q=[(r,c)];seen.add((r,c));p=[]
                while q:
                    a,b=q.pop();p.append((a,b))
                    for x,y in [(a-1,b),(a+1,b),(a,b-1),(a,b+1)]:
                        if 0<=x<h and 0<=y<w and grid[x][y] and (x,y) not in seen:
                            seen.add((x,y));q.append((x,y))
                comps.append(p)
    if len(comps)>=2:
        centers=[(sum(a for a,b in p)/len(p),sum(b for a,b in p)/len(p)) for p in comps]
        vertical=max(a for a,b in centers)-min(a for a,b in centers)>=max(b for a,b in centers)-min(b for a,b in centers)
    else:
        p=[(r,c) for r in range(h) for c in range(w) if grid[r][c]]
        vertical=bool(p) and max(r for r,c in p)-min(r for r,c in p)>max(c for r,c in p)-min(c for r,c in p)
    if vertical:
        for r in range(h): out[r][0]=1
    else: out[0]=[1]*w
    return out

